'use strict';
const root=document.querySelector('#app'),notice=document.querySelector('#notice');
let state=null,page='Dashboard',selected=1,credentials=[];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
selected=(SESSIONS.find(s=>s.date>=today)||SESSIONS.at(-1)).id;
const options=(items,value)=>items.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('');
const sessions=()=>SESSIONS.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${s.date} · ${esc(s.title)}</option>`).join('');
function message(t){notice.textContent=t;}
async function api(path,body){const response=await fetch(path.startsWith('/kite')?path:'/nycmccompass/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed. Please try again.');return result;}
async function refresh(){state=await api('state');render();}
function login(){state=null;root.innerHTML=`<main class="login-page"><section class="login-panel" aria-label="COMPASS portal sign in"><div class="login-art"><div class="login-brand">COMPASS<span>NYCMC TECH CLASS</span></div><svg viewBox="0 0 480 360" aria-hidden="true"><ellipse cx="242" cy="325" rx="209" ry="18" fill="#e9f0f8"/><rect x="45" y="48" width="360" height="240" rx="90" fill="#f0f6fc"/><rect x="77" y="78" width="78" height="53" rx="12" fill="#dcecff"/><text x="93" y="112" fill="#3885da" font-size="25" font-family="monospace">&lt;/&gt;</text><path d="M344 252q-35-72 5-103q27 45-5 103M350 255q0-60 46-65q0 53-46 65" fill="#8bc6b0"/><path d="M327 248h48l-7 38h-34z" fill="#90a5bd"/><rect x="72" y="277" width="339" height="12" rx="6" fill="#c39873"/><path d="M95 289l-12 48m302-48l12 48" stroke="#34465d" stroke-width="9"/><path d="M160 195q-10-35 23-46h39q32 8 38 52l-26 67h-90z" fill="#428ee5"/><circle cx="203" cy="117" r="34" fill="#efbf9f"/><path d="M170 116q-16-53 32-47q41 0 35 44l-15-24q-22 15-48 10z" fill="#34465d"/><path d="M164 185l-26 63h66m35-55l20 54h30" fill="none" stroke="#efbf9f" stroke-width="17" stroke-linecap="round"/><path d="M170 276l20 48m32-48l23 48" stroke="#34465d" stroke-width="23"/><path d="M181 329h31m27 0h29" stroke="#428ee5" stroke-width="13" stroke-linecap="round"/><path d="M237 211h92l-16 61h-92z" fill="#34465d"/><path d="M220 273h107" stroke="#687c95" stroke-width="7" stroke-linecap="round"/><circle cx="277" cy="240" r="7" fill="#a8cef5"/><rect x="102" y="262" width="54" height="10" rx="3" fill="#8bc6b0"/></svg><p>A place to learn. A space to create.</p></div><div class="login-fields"><h1>Welcome back</h1><p class="login-subtitle">Sign in to your tech class.</p><div class="login-switch" role="group" aria-label="Choose login type" data-role="student"><span class="login-slider" aria-hidden="true"></span><button type="button" data-login-role="teacher" aria-pressed="false">Teacher Login</button><button type="button" data-login-role="student" aria-pressed="true">Student Login</button></div><form data-form="login" class="portal-login"><label for="login-id" id="login-id-label">Student ID</label><input id="login-id" name="id" autocomplete="username" required maxlength="11" placeholder="Enter your student ID" autocapitalize="none" spellcheck="false"><label for="login-secret" id="login-secret-label">4-digit code</label><div class="secret-field"><input id="login-secret" name="code" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="current-password" required placeholder="Enter your 4-digit code"><button type="button" data-action="toggle-secret" aria-label="Show code" aria-pressed="false">Show</button></div><button type="submit" class="login-submit">Log in</button><p class="login-help" id="login-help">Need help signing in? Ask your teacher.</p></form></div></section></main>`;}
function chooseLoginRole(role){const teacher=role==='teacher',form=root.querySelector('.portal-login'),secret=root.querySelector('#login-secret'),id=root.querySelector('#login-id');form.reset();form.dataset.form=teacher?'teacher':'login';root.querySelector('.login-switch').dataset.role=role;root.querySelectorAll('[data-login-role]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.loginRole===role)));root.querySelector('#login-id-label').textContent=teacher?'User ID':'Student ID';id.placeholder=teacher?'Enter your user ID':'Enter your student ID';if(teacher)id.removeAttribute('maxlength');else id.maxLength=11;root.querySelector('#login-secret-label').textContent=teacher?'Password':'4-digit code';secret.name=teacher?'password':'code';secret.type='password';secret.placeholder=teacher?'Enter your password':'Enter your 4-digit code';if(teacher){secret.removeAttribute('pattern');secret.removeAttribute('maxlength');secret.removeAttribute('inputmode');}else{secret.pattern='[0-9]{4}';secret.maxLength=4;secret.inputMode='numeric';}const toggle=root.querySelector('[data-action="toggle-secret"]');toggle.textContent='Show';toggle.setAttribute('aria-pressed','false');toggle.setAttribute('aria-label',teacher?'Show password':'Show code');root.querySelector('#login-help').textContent=teacher?'Use your existing instructor account.':'Need help signing in? Ask your teacher.';message('');}

function render(){const teacher=state.role==='teacher',student=state.students[0];const pages=teacher?['Dashboard','Attendance','Progress','Students','Projects','Roadmap']:['Dashboard','Roadmap','Projects'];root.innerHTML=`<div class="shell"><aside><div class="brand"><span class="logo">⌘</span><div>COMPASS<small>LEARNING LAB</small></div></div><div class="cohort">NYCMC / WELLSPRING<span>Grades 6–8 · 2026–27</span></div><nav>${pages.map(p=>`<button data-page="${p}" class="${page===p?'active':''}">${p}</button>`).join('')}</nav><div class="aside-bottom"><strong>Small steps.<br>Big discoveries.</strong><p>49 sessions of making things.</p></div></aside><div class="workspace"><header><span>${teacher?'Instructor workspace':esc(student.name)}</span><div><button data-action="refresh">Refresh</button> <button data-action="logout">Sign out</button></div></header><main><div class="eyebrow">INFORMATION TECHNOLOGY / COMPUTER LITERACY</div><h1>${page==='Dashboard'?(teacher?'Ready for the next discovery?':`Welcome, ${esc(student.name)}!`):page}</h1>${content(teacher,student)}</main></div></div>`;}
function lesson(){const s=SESSIONS.find(s=>s.id===selected);return `<section class="card"><label>Session<select id="session">${sessions()}</select></label><p class="eyebrow">SESSION ${s.id} · ${esc(MODULES[s.module][0])}</p><h2>${esc(s.title)}</h2><p><strong>Your goal:</strong> ${esc(s.objective)}</p><p>${esc(s.activity)}</p><p><strong>Tools:</strong> ${esc(s.tool)}</p><p class="muted">5 min warm-up · 10 min demo · 35 min pair building · 5 min share · 5 min reflection</p><p>Pair up: one person drives, one explains and checks. Switch halfway. If stuck, predict → run → compare → change one thing.</p></section>`;}
function content(teacher,s){if(page==='Roadmap')return `<p>Explore at your pace. Your instructor marks module milestones.</p>${MODULES.map((m,i)=>`<section class="card"><h2>${i+1}. ${esc(m[0])}</h2><p>${esc(m[1])} · Sessions ${m[2]}–${m[3]}</p>${!teacher?`<strong>${esc(s.progress[i])}</strong>`:''}<details><summary>View lessons</summary>${SESSIONS.filter(x=>x.module===i).map(x=>`<p><button data-lesson="${x.id}">${x.date} · ${esc(x.title)}</button> ${esc(x.objective)}</p>`).join('')}</details></section>`).join('')}`;
if(page==='Dashboard'){if(teacher)return `<div class="cards"><section class="card"><h2>${state.students.filter(s=>s.active).length} active learners</h2><p>${state.students.filter(s=>s.help).length} raised hands</p>${state.students.filter(s=>s.help).map(s=>`<p>${esc(s.name)} <button data-help="${s.id}">Help received ✓</button></p>`).join('')||'<p>No hands raised.</p>'}</section><section class="card"><h2>Teaching rhythm</h2><p>Keep demonstrations under 15 minutes. Use starter code, pairs, and visual debugging.</p><p>Simplify memory into labeled boxes; skip C pointers, manual allocation, advanced recursion, and university problem-set grading.</p></section></div>${lesson()}`;
const done=s.progress.filter(p=>p==='Completed').length;return `<section class="card"><h2>${done} of 6 milestones earned</h2><progress max="6" value="${done}" aria-label="Module progress"></progress><p>${MODULES.filter((m,i)=>s.progress[i]==='Completed').map(m=>`<span class="badge">★ ${esc(m[4])}</span>`).join(' ')||'Your first badge is waiting. Start by trying today’s activity.'}</p><button data-action="help" class="primary">${s.help?'Hand raised — click to lower':'✋ I need help'}</button>${s.feedback?`<p><strong>Instructor feedback:</strong> ${esc(s.feedback)}</p>`:''}</section>${lesson()}<section class="card"><h2>My session checklist</h2>${['I opened my project','I tried the challenge','I tested and fixed something','I saved and explained my work'].map((t,i)=>`<label class="check"><input type="checkbox" data-check="${i}" ${(s.checks[selected]||[])[i]?'checked':''}>${t}</label>`).join('')}</section>`;}
if(page==='Attendance')return `<p>Choose a date to mark attendance. Unmarked is not absent.</p><label>Session<select id="session">${sessions()}</select></label><div class="table-wrap"><table><thead><tr><th>Student</th><th>${SESSIONS[selected-1].date}</th></tr></thead><tbody>${state.students.filter(s=>s.active).map(s=>`<tr><th>${esc(s.name)}</th><td><select aria-label="Attendance for ${esc(s.name)}" data-attendance="${s.id}">${options(['Unmarked','Present','Absent','Tardy','Excused'],s.attendance[SESSIONS[selected-1].date]||'Unmarked')}</select></td></tr>`).join('')}</tbody></table></div><button data-action="csv">Export all attendance and progress CSV</button><details class="card"><summary>Full attendance grid</summary><div class="table-wrap"><table><tr><th>Student</th>${SESSIONS.map(s=>`<th>${s.date}</th>`).join('')}</tr>${state.students.map(s=>`<tr><th>${esc(s.name)}</th>${SESSIONS.map(d=>`<td>${esc(s.attendance[d.date]||'Unmarked')}</td>`).join('')}</tr>`).join('')}</table></div></details>`;
if(page==='Progress')return `<div class="table-wrap"><table><tr><th>Student</th>${MODULES.map(m=>`<th>${esc(m[0])}</th>`).join('')}</tr>${state.students.map(s=>`<tr><th>${esc(s.name)}</th>${s.progress.map((p,i)=>`<td><select aria-label="${esc(s.name)} ${esc(MODULES[i][0])}" data-progress="${s.id}" data-module="${i}">${options(['Not Started','In Progress','Completed'],p)}</select></td>`).join('')}</tr>`).join('')}</table></div><button data-action="csv">Export report CSV</button>`;
if(page==='Students')return `<section class="card"><h2>Create a student</h2><form data-form="create"><label>First name + last initial, or nickname<input name="name" required maxlength="40"></label><label>Grade<select name="grade">${options(['6','7','8'],'6')}</select></label><button class="primary">Create student</button></form><details><summary>Import roster CSV</summary><p>Headers: name,grade. Use nicknames or first name and last initial.</p><input id="import" type="file" accept=".csv,text/csv"><div id="preview"></div></details></section>${credentials.length?`<section class="card"><h2>New sign-in cards</h2><p>Codes are displayed only now. Download and give each student only their own card.</p><button data-action="codes">Download private sign-in CSV</button><button data-action="hidecodes">Hide codes</button><pre>${credentials.map(c=>esc(`${c.name} — ${c.id} — ${c.code}`)).join('\n')}</pre></section>`:''}${state.students.map(s=>`<details class="card"><summary>${esc(s.name)} · Grade ${s.grade} · ${s.active?'Active':'Inactive'}</summary><p>Student ID: ${esc(s.id)}</p><button data-reset="${s.id}">Reset join code</button> <button data-active="${s.id}">${s.active?'Deactivate':'Reactivate'}</button><form data-form="notes" data-id="${s.id}"><label>Feedback visible to student<textarea name="feedback" maxlength="2000">${esc(s.feedback)}</textarea></label><label>Instructor-only note<textarea name="note" maxlength="2000">${esc(s.note)}</textarea></label><button>Save notes</button></form></details>`).join('')}`;
if(page==='Projects')return `${!teacher?`<section class="card"><h2>Share something you made</h2><form data-form="project"><label>Session<select name="session">${sessions()}</select></label><label>Project title<input name="title" required maxlength="100"></label><label>Scratch or code URL<input name="url" type="url" required maxlength="2000"></label><label>What did you try, fix, or learn?<textarea name="reflection" required maxlength="2000"></textarea></label><p class="tiny">Share only your project. Leave personal information out.</p><button class="primary">Submit project</button></form></section>`:''}${state.students.flatMap(s=>s.projects.map(p=>`<section class="card"><h2>${esc(p.title)}</h2><p>${esc(s.name)} · Session ${p.session} · ${esc(p.status)}</p><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Open project ↗</a><p>${esc(p.reflection)}</p>${teacher?`<form data-form="review" data-id="${s.id}" data-project="${p.id}"><label>Status<select name="status">${options(['Submitted','Needs Revision','Complete'],p.status)}</select></label><label>Feedback<textarea name="feedback" maxlength="2000">${esc(p.feedback)}</textarea></label><button>Save review</button></form>`:`<p>${esc(p.feedback)}</p>`}</section>`)).join('')||'<p>No projects yet. Your first experiment counts!</p>'}`;return '';}
function download(name,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let imported=[];
root.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),button=f.querySelector('button[type=submit]')||f.querySelector('button');button.disabled=true;try{switch(f.dataset.form){case 'login':await api('login',b);page='Dashboard';break;case 'teacher':await api('logout',{});await api('/kite/api/admin/login',b);page='Dashboard';break;case 'create':credentials.push(await api('create',b));break;case 'notes':await api('update',{...b,id:f.dataset.id,action:'notes'});break;case 'review':await api('update',{...b,id:f.dataset.id,project:f.dataset.project,action:'review'});break;case 'project':await api('student',{...b,session:Number(b.session),action:'project'});break;}await refresh();message('Saved successfully.');}catch(err){message(err.message);}finally{button.disabled=false;}});
root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.loginRole){chooseLoginRole(b.dataset.loginRole);return;}if(b.dataset.action==='toggle-secret'){const input=root.querySelector('#login-secret'),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',(show?'Hide ':'Show ')+(input.name==='code'?'code':'password'));return;}if(b.dataset.page){page=b.dataset.page;render();return;}if(b.dataset.lesson){selected=Number(b.dataset.lesson);page='Dashboard';render();return;}const a=b.dataset.action;if(a==='logout'){await api('logout',{});if(state?.role==='teacher')await api('/kite/api/admin/logout',{});credentials=[];login();message('Signed out.');return;}if(a==='refresh'){await refresh();message('Up to date.');}if(a==='help'){await api('student',{action:'help',value:!state.students[0].help});await refresh();}if(b.dataset.help){await api('update',{id:b.dataset.help,action:'help'});await refresh();}if(b.dataset.reset){if(!confirm('Replace this student’s code and sign them out?'))return;credentials.push(await api('reset',{id:b.dataset.reset}));render();}if(b.dataset.active){const s=state.students.find(s=>s.id===b.dataset.active);await api('update',{id:s.id,action:'active',value:!s.active});await refresh();}if(a==='hidecodes'){credentials=[];render();}if(a==='codes')download('compass-private-sign-in-cards.csv',[['name','student_id','code'],...credentials.map(c=>[c.name,c.id,c.code])]);if(a==='import'){const result=await api('import',{students:imported});credentials.push(...result.created);imported=[];await refresh();message(`${result.created.length} students created. Existing nickname/grade matches skipped.`);}if(a==='csv')download('compass-progress-attendance.csv',[['student_id','name','grade','active',...MODULES.map(m=>m[0]),...SESSIONS.map(s=>s.date),'submitted_projects'],...state.students.map(s=>[s.id,s.name,s.grade,s.active,...s.progress,...SESSIONS.map(d=>s.attendance[d.date]||'Unmarked'),s.projects.length])]);}catch(err){message(err.message);}});
root.addEventListener('change',async e=>{const t=e.target;try{if(t.id==='session'){selected=Number(t.value);render();return;}if(t.id==='import'){const file=t.files[0];if(!file)return;if(file.size>20000)throw Error('Roster must be under 20 KB.');const lines=(await file.text()).replace(/^\ufeff/,'').trim().split(/\r?\n/);if(lines.shift().toLowerCase()!=='name,grade')throw Error('CSV headers must be name,grade.');imported=lines.map(line=>{const parts=line.split(',');if(parts.length!==2)throw Error('Use simple names without commas.');return {name:parts[0].trim(),grade:Number(parts[1])};});if(!imported.length||imported.length>100||imported.some(s=>!s.name||s.name.length>40||![6,7,8].includes(s.grade)))throw Error('Check names and grades (6–8), maximum 100 rows.');document.querySelector('#preview').innerHTML=`<p>${imported.length} students:</p><p>${imported.map(s=>esc(s.name)+' ('+s.grade+')').join(', ')}</p><button data-action="import">Import these students</button>`;return;}if(t.dataset.check!==undefined){const value=[...root.querySelectorAll('[data-check]')].map(x=>x.checked);await api('student',{action:'checks',session:selected,value});state.students[0].checks[selected]=value;}if(t.dataset.attendance)await api('update',{id:t.dataset.attendance,action:'attendance',date:SESSIONS[selected-1].date,value:t.value});if(t.dataset.progress)await api('update',{id:t.dataset.progress,action:'progress',module:Number(t.dataset.module),value:t.value});if(t.dataset.attendance||t.dataset.progress)await refresh();message('Saved.');}catch(err){message(err.message);if(state)await refresh().catch(()=>{});}});
refresh().catch(err=>{login();if(err.message!=='Please sign in.')message(err.message);});
// Refresh the raised-hand overview without interrupting any student or instructor form.
setInterval(()=>{if(state?.role==='teacher'&&page==='Dashboard'&&!document.hidden)refresh().catch(err=>message(err.message));},20000);
